#!/usr/bin/env python3
import argparse,csv,json
from pathlib import Path
def main():
 p=argparse.ArgumentParser();p.add_argument('--metrics',required=True);p.add_argument('--effects',required=True);p.add_argument('--main-id',required=True);p.add_argument('--output',required=True);p.add_argument('--report',required=True);a=p.parse_args(); rows=list(csv.DictReader(open(a.effects))); get={x['variant_id']:x for x in rows}; alt=all(float(get[v]['alternative_support_delta'])>=.15 for v in ['collapse_alternative_to_A_first','collapse_alternative_to_B_first']); rec=float(get['remove_recovery_edge']['recovery_support_delta'])>=.25; debt=float(get['no_recovery_debt_cap']['debt_cap_overshoot_delta'])>0; phi=float(get['no_phi']['within_node_density_delta'])<=-.05 or float(get['cost_only']['within_node_density_delta'])<=-.05; out={'decision':'CORE_REWARD_ABLATIONS_COMPLETE' if alt and rec else 'CORE_REWARD_CLAIM_WEAK','alternative_structural_support':alt,'recovery_structural_support':rec,'debt_cap_empirical_support':debt,'within_node_progress_support':phi,'jobs':56,'probes_posthoc_only':True};Path(a.output).parent.mkdir(parents=True,exist_ok=True);Path(a.output).write_text(json.dumps(out,indent=2)+'\n');Path(a.report).write_text('# Core ablation gate\n\n'+json.dumps(out,indent=2)+'\n');print(json.dumps(out,indent=2));return 0 if out['decision']=='CORE_REWARD_ABLATIONS_COMPLETE' else 2
if __name__=='__main__':raise SystemExit(main())
